DROP TABLE IF EXISTS reservas;
CREATE TABLE `reservas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cliente_id` int DEFAULT NULL,
  `caballo_id` int DEFAULT NULL,
  `instructora_id` int DEFAULT NULL,
  `clase_id` int DEFAULT NULL,
  `fecha` date DEFAULT NULL,
  `hora_inicio` time DEFAULT NULL,
  `hora_fin` time DEFAULT NULL,
  `estatus` enum('pendiente','confirmada','cancelada','completada','cancelada_instructor') DEFAULT 'pendiente',
  `tipo` enum('normal','propietario','renta','media_renta') DEFAULT 'normal',
  `observaciones` text,
  `motivo_cancelacion` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `cliente_id` (`cliente_id`),
  KEY `caballo_id` (`caballo_id`),
  KEY `instructora_id` (`instructora_id`),
  KEY `clase_id` (`clase_id`),
  KEY `idx_reservas_fecha` (`fecha`),
  KEY `idx_reservas_fecha_estatus` (`fecha`,`estatus`),
  KEY `idx_reservas_caballo_fecha` (`caballo_id`,`fecha`),
  KEY `idx_reservas_fecha_horas` (`fecha`,`hora_inicio`,`hora_fin`),
  KEY `idx_reservas_instructora_fecha` (`instructora_id`,`fecha`),
  CONSTRAINT `reservas_ibfk_2` FOREIGN KEY (`caballo_id`) REFERENCES `caballos` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reservas_ibfk_3` FOREIGN KEY (`instructora_id`) REFERENCES `instructoras` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reservas_ibfk_4` FOREIGN KEY (`clase_id`) REFERENCES `clases` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1887 DEFAULT CHARSET=utf8mb3;

